column1:
// Runde 47: Voreinstellung des Finalisierer-Verteilers. Das Programm
// deklariert keinen eigenen, also tut das Aufraeumen nichts.
fn __gc_finalize(kind: u64, p: *mut u8) {
    let _unused: u64 = kind + (p as u64)
}

column2:
// Round 47: default of the finalizer dispatcher. The program
// declares none of its own, so cleanup does nothing.
fn __gc_finalize(kind: u64, p: *mut u8) {
    let _unused: u64 = kind + (p as u64)
}

column1:
// Runde 49: Voreinstellung des Fadenverteilers. Das Programm
// deklariert keinen eigenen, also tut ein Faden nichts.
fn __thread_work(kind: u64, arg: u64) -> u64 {
    return kind + arg - kind - arg
}

column2:
// Round 49: default of the thread dispatcher. The program
// declares none of its own, so a thread does nothing.
fn __thread_work(kind: u64, arg: u64) -> u64 {
    return kind + arg - kind - arg
}
